script:
// Client Script for JobEstimation doctype
// This script will automatically calculate total_estimation_amount when complete_cost changes

frappe.ui.form.on('JobEstimation', {
    refresh: function(frm) {
        // Calculate total when form loads
        calculate_total_estimation_amount(frm);
    }
});

frappe.ui.form.on('Materials Required_BOQ', {
    complete_cost: function(frm, cdt, cdn) {
        // Calculate total when complete_cost changes
        calculate_total_estimation_amount(frm);
    },
    
    boq_add: function(frm, cdt, cdn) {
        // Calculate total when new row is added
        calculate_total_estimation_amount(frm);
    },
    
    boq_remove: function(frm, cdt, cdn) {
        // Calculate total when row is removed
        calculate_total_estimation_amount(frm);
    }
});

function calculate_total_estimation_amount(frm) {
    let total = 0;
    
    // Loop through all rows in BOQ table
    frm.doc.boq.forEach(function(row) {
        if (row.complete_cost) {
            total += flt(row.complete_cost);
        }
    });
    
    // Set the total_estimation_amount field
    frm.set_value('total_estimation_amount', total);
}

// Working Client Script for Resources Availability
frappe.ui.form.on('Resources Availabilty', {
    // Test on refresh
    refresh: function(frm) {
        console.log('=== FORM REFRESH ===');
        console.log('DocType:', frm.doctype);
        console.log('Current Job Estimation:', frm.doc.job_estimation);
        
        // Add button to manually trigger
        frm.add_custom_button(__('Load Materials'), function() {
            load_materials(frm);
        });
    },
    
    // Test on job_estimation change
    job_estimation: function(frm) {
        console.log('=== JOB ESTIMATION CHANGED ===');
        console.log('New Value:', frm.doc.job_estimation);
        frappe.msgprint('Job Estimation Changed: ' + frm.doc.job_estimation);
        
        if (frm.doc.job_estimation) {
            load_materials(frm);
        }
    },
    
    // Test on validate
    validate: function(frm) {
        console.log('=== FORM VALIDATE ===');
        console.log('Job Estimation:', frm.doc.job_estimation);
    }
});

// Function to load materials
function load_materials(frm) {
    console.log('=== LOAD MATERIALS FUNCTION ===');
    console.log('Loading materials for:', frm.doc.job_estimation);
    
    if (!frm.doc.job_estimation) {
        frappe.msgprint('Please select a Job Estimation first');
        return;
    }
    
    // Clear existing data
    frm.clear_table('raw_material_availabilty');
    
    // Show loading message
    frappe.msgprint('Loading materials...');
    
    // Get BOQ data
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'BOQ',
            filters: {
                parent: frm.doc.job_estimation
            },
            fields: ['name', 'bom']
        },
        callback: function(r) {
            console.log('BOQ Response:', r);
            
            if (r.message && r.message.length > 0) {
                console.log('Found BOQ items:', r.message.length);
                frappe.msgprint('Found ' + r.message.length + ' BOQ items');
                
                let total_boms = r.message.filter(item => item.bom).length;
                let processed_boms = 0;
                
                // Process each BOQ item
                r.message.forEach(function(boq_item) {
                    console.log('Processing BOQ:', boq_item);
                    
                    if (boq_item.bom) {
                        // Get BOM items
                        frappe.call({
                            method: 'frappe.client.get_list',
                            args: {
                                doctype: 'BOM Item',
                                filters: {
                                    parent: boq_item.bom
                                },
                                fields: ['item_name', 'qty']
                            },
                            callback: function(bom_response) {
                                console.log('BOM Response for', boq_item.bom, ':', bom_response);
                                
                                if (bom_response.message && bom_response.message.length > 0) {
                                    console.log('Found BOM items:', bom_response.message.length);
                                    
                                    // Add items to child table
                                    bom_response.message.forEach(function(item) {
                                        console.log('Adding item:', item);
                                        let row = frm.add_child('raw_material_availabilty');
                                        row.item_name = item.item_name;
                                        row.qty = item.qty;
                                    });
                                    
                                    // Refresh table
                                    frm.refresh_field('raw_material_availabilty');
                                } else {
                                    console.log('No BOM items found for:', boq_item.bom);
                                }
                                
                                processed_boms++;
                                if (processed_boms === total_boms) {
                                    frappe.msgprint('All materials loaded successfully!');
                                    console.log('=== LOADING COMPLETE ===');
                                }
                            }
                        });
                    }
                });
            } else {
                console.log('No BOQ items found');
                frappe.msgprint('No BOQ items found for this job estimation');
            }
        }
    });
}

frappe.ui.form.on('EstimateBudget', {
    // Trigger when 'from' field changes
    from: function(frm) {
        update_estimate_range(frm);
    },

    // Trigger when 'to' field changes
    to: function(frm) {
        update_estimate_range(frm);
    }
});

function update_estimate_range(frm) {
    const from_value = frm.doc.from;
    const to_value = frm.doc.to;

    // Only proceed if 'from' field has a value
    if (!from_value) {
        frm.set_value('estimate_range', '');
        return;
    }

    // Get default currency from ERPNext system settings
    const default_currency = frappe.defaults.get_default("currency") || frappe.boot.sysdefaults.currency || "USD";

    let estimate_range = '';

    // Format the range based on conditions
    if (to_value === 0 || !to_value) {
        // If 'to' is 0 or empty, add "& more"
        estimate_range = `${default_currency} ${format_currency(from_value)} & more`;
    } else {
        // Normal range format
        estimate_range = `${default_currency} ${format_currency(from_value)} - ${default_currency} ${format_currency(to_value)}`;
    }

    // Set the calculated value to estimate_range field
    frm.set_value('estimate_range', estimate_range);
}

function format_currency(amount) {
    // Convert number to string and add commas for thousands
    return amount.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

frappe.ui.form.on('Job Estimation', {
    refresh(frm) {
        // Add custom buttons
        if (frm.doc.docstatus === 0) {
            // Extract Materials Button
            frm.add_custom_button(__('Extract Materials from BOMs'), function() {
                if (!frm.doc.boq || frm.doc.boq.length === 0) {
                    frappe.msgprint(__('Please add BoQ items first'));
                    return;
                }

                frappe.confirm(
                    __('This will extract and consolidate all materials from BOMs in BoQ. Continue?'),
                    function() {
                        frappe.call({
                            method: 'your_app.api.extract_materials_from_boms',
                            args: {
                                doc_name: frm.doc.name
                            },
                            callback: function(r) {
                                if (r.message) {
                                    frm.reload_doc();
                                }
                            }
                        });
                    }
                );
            }, __('Materials'));

            // Check Availability Button
            frm.add_custom_button(__('Check Material Availability'), function() {
                if (!frm.doc.materials || frm.doc.materials.length === 0) {
                    frappe.msgprint(__('No materials found. Please extract materials first.'));
                    return;
                }

                frappe.call({
                    method: 'your_app.api.check_material_availability',
                    args: {
                        doc_name: frm.doc.name
                    },
                    callback: function(r) {
                        frm.reload_doc();
                    }
                });
            }, __('Materials'));

            // Create Material Request Button
            frm.add_custom_button(__('Create Material Request'), function() {
                if (!frm.doc.materials || frm.doc.materials.length === 0) {
                    frappe.msgprint(__('No materials found. Please check availability first.'));
                    return;
                }

                frappe.confirm(
                    __('This will create Material Request for items with shortage. Continue?'),
                    function() {
                        frappe.call({
                            method: 'your_app.api.create_material_request',
                            args: {
                                doc_name: frm.doc.name
                            },
                            callback: function(r) {
                                if (r.message) {
                                    frm.reload_doc();
                                }
                            }
                        });
                    }
                );
            }, __('Materials'));
        }
    },

    // Auto-calculate totals when materials change
    materials_on_form_rendered(frm) {
        calculate_totals(frm);
    }
});

frappe.ui.form.on('Job Estimation Material', {
    required_qty(frm, cdt, cdn) {
        calculate_row_amount(frm, cdt, cdn);
        calculate_totals(frm);
    },

    rate(frm, cdt, cdn) {
        calculate_row_amount(frm, cdt, cdn);
        calculate_totals(frm);
    }
});

function calculate_row_amount(frm, cdt, cdn) {
    let row = locals[cdt][cdn];
    row.amount = (row.required_qty || 0) * (row.rate || 0);
    frm.refresh_field('materials');
}

function calculate_totals(frm) {
    let total_cost = 0;

    if (frm.doc.materials) {
        frm.doc.materials.forEach(function(row) {
            total_cost += (row.amount || 0);
        });
    }

    frm.set_value('total_material_cost', total_cost);
}

frappe.ui.form.on('JobEstimation', {
    refresh: function(frm) {
        calculate_estimated_end_date(frm);
        generate_item_summary(frm); // Add item summary generation

        frm.add_custom_button(__('Calculate End Date'), function() {
            calculate_estimated_end_date(frm);
        });

        frm.add_custom_button(__('Generate Item Summary'), function() {
            generate_item_summary(frm);
        });
    },

    estimated_start_date: function(frm) {
        calculate_estimated_end_date(frm);
        update_operation_dates(frm);
    },

    siteinspection: function(frm) {
        if (frm.doc.siteinspection) {
            frappe.call({
                method: 'frappe.client.get',
                args: {
                    doctype: 'SiteInspection',
                    name: frm.doc.siteinspection
                },
                callback: function(r) {
                    console.log("📦 SiteInspection Response:", r.message);

                    if (r.message && r.message.site_dimensions) {
                        frm.clear_table('site_dimensions');
                        frm.clear_table('boq');

                        let all_images = [];
                        let entitySet = new Set();

                        r.message.site_dimensions.forEach((row) => {
                            let new_row = frm.add_child('site_dimensions');
                            new_row.no = row.no;
                            new_row.floor = row.floor;
                            new_row.room = row.room;
                            new_row.entity = row.entity;
                            new_row.area_name = row.area_name;
                            new_row.dimensionsunits = row.dimensionsunits;
                            new_row.media = row.media;

                            if (row.media) {
                                new_row.media_preview = `<img src="${row.media}" style="width: 60px; height: 60px; object-fit: cover; border-radius: 4px;">`;
                                all_images.push({
                                    image: row.media,
                                    caption: `${row.floor || ''} - ${row.room || ''} - ${row.area_name || ''} (Media)`,
                                    type: 'media'
                                });
                            }

                           if ((row.entity || row.area_name) && !entitySet.has(row.entity || row.area_name)) {
    let boq_row = frm.add_child('boq');
    // boq_row.entity = row.entity || ''; // If entity missing, set as empty string
    boq_row.entity = [row.entity, row.area_name].filter(Boolean).join(' ');
    boq_row.description = `${row.floor || ''} - ${row.room || ''} - ${row.area_name || ''}`;
    entitySet.add(row.entity || row.area_name);
}

                        });

                        if (r.message.site_photos) {
                            all_images.push({
                                image: r.message.site_photos,
                                caption: `${r.message.name || 'Site Inspection'} (Site Photos)`,
                                type: 'site_photos'
                            });
                        }

                        if (r.message.measurement_sketch) {
                            all_images.push({
                                image: r.message.measurement_sketch,
                                caption: `${r.message.name || 'Site Inspection'} (Measurement Sketch)`,
                                type: 'measurement_sketch'
                            });
                        }

                        frm.refresh_field('site_dimensions');
                        frm.refresh_field('boq');
                        show_all_images_separately(frm, all_images);

                        frm.fields_dict.site_dimensions.grid.cannot_add_rows = true;
                        frm.fields_dict.site_dimensions.grid.cannot_delete_rows = true;

                        frappe.show_alert({ message: 'Site Dimensions loaded!', indicator: 'green' });
                    } else {
                        frappe.show_alert({ message: 'No Site Dimensions found!', indicator: 'yellow' });
                    }
                }
            });
        } else {
            frm.clear_table('site_dimensions');
            frm.clear_table('boq');
            frm.refresh_field('site_dimensions');
            frm.refresh_field('boq');
            if ($('#all-images-container').length) {
                $('#all-images-container').html('');
            }
        }
    }
});

frappe.ui.form.on('Materials Required_BOQ', {
    bom: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        if (row.bom) {
            frappe.call({
                method: 'frappe.client.get',
                args: {
                    doctype: 'BOM',
                    name: row.bom
                },
                callback: function(r) {
                    if (r.message) {
                        let bom_cost = r.message.total_cost || 0;
                        frappe.model.set_value(cdt, cdn, 'complete_cost', bom_cost);
                        update_total_estimation(frm);
                        generate_item_summary(frm); // Regenerate item summary
                    }
                }
            });
        } else {
            frappe.model.set_value(cdt, cdn, 'complete_cost', 0);
            update_total_estimation(frm);
            generate_item_summary(frm); // Regenerate item summary
        }
    },

    complete_cost: function(frm) {
        update_total_estimation(frm);
        generate_item_summary(frm); // Regenerate item summary
    }
});

frappe.ui.form.on('execution_work', {
    time: function(frm, cdt, cdn) {
        calculate_estimated_end_date(frm);
        update_operation_dates(frm);
    },

    tentative_schedule_for_execution_add: function(frm) {
        set_next_operation_date(frm);
        calculate_estimated_end_date(frm);
    },

    tentative_schedule_for_execution_remove: function(frm) {
        calculate_estimated_end_date(frm);
        update_operation_dates(frm);
    }
});

// =======================
// 🔧 Utilities Below
// =======================

function update_total_estimation(frm) {
    let total = 0;
    (frm.doc.boq || []).forEach(row => {
        total += flt(row.complete_cost);
    });
    frm.set_value('total_estimation_amount', total);
    frm.refresh_field('total_estimation_amount');
}

function calculate_estimated_end_date(frm) {
    let total_time = 0;
    let start_date = frm.doc.estimated_start_date;

    if (!start_date) {
        frm.set_value('estimated_end_date', '');
        return;
    }

    if (frm.doc.tentative_schedule_for_execution && frm.doc.tentative_schedule_for_execution.length > 0) {
        frm.doc.tentative_schedule_for_execution.forEach(row => {
            if (row.time && !isNaN(parseFloat(row.time))) {
                total_time += parseFloat(row.time);
            }
        });
    }

    let total_days = Math.ceil(total_time / 8);

    if (total_days > 0) {
        let start_date_obj = new Date(start_date);
        if (!isNaN(start_date_obj.getTime())) {
            start_date_obj.setDate(start_date_obj.getDate() + total_days);
            let end_date = start_date_obj.toISOString().split('T')[0];
            frm.set_value('estimated_end_date', end_date);
        }
    } else {
        frm.set_value('estimated_end_date', '');
    }
}

function set_next_operation_date(frm) {
    let rows = frm.doc.tentative_schedule_for_execution || [];

    if (rows.length > 0) {
        let last_row = rows[rows.length - 1];
        let previous_row = rows[rows.length - 2];

        if (rows.length === 1) {
            if (frm.doc.estimated_start_date) {
                frappe.model.set_value(last_row.doctype, last_row.name, 'date', frm.doc.estimated_start_date);
            }
        } else if (previous_row && previous_row.date && previous_row.time) {
            let prev_start = new Date(previous_row.date);
            let prev_days = Math.ceil(parseFloat(previous_row.time || 0) / 8);
            prev_start.setDate(prev_start.getDate() + prev_days);
            let next_date = prev_start.toISOString().split('T')[0];
            frappe.model.set_value(last_row.doctype, last_row.name, 'date', next_date);
        }
    }
}

function update_operation_dates(frm) {
    let rows = frm.doc.tentative_schedule_for_execution || [];

    rows.forEach((row, index) => {
        if (index === 0) {
            if (frm.doc.estimated_start_date) {
                frappe.model.set_value(row.doctype, row.name, 'date', frm.doc.estimated_start_date);
            }
        } else {
            let previous_row = rows[index - 1];
            if (previous_row.date && previous_row.time) {
                let prev_start = new Date(previous_row.date);
                let prev_days = Math.ceil(parseFloat(previous_row.time || 0) / 8);
                prev_start.setDate(prev_start.getDate() + prev_days);
                let next_date = prev_start.toISOString().split('T')[0];
                frappe.model.set_value(row.doctype, row.name, 'date', next_date);
            }
        }
    });
}

// ✅ Show images in 3 sections
function show_all_images_separately(frm, images) {
    const categorized = {
        media: [],
        site_photos: [],
        measurement_sketch: []
    };

    images.forEach(img => {
        const fullUrl = img.image.startsWith('http') ? img.image : window.location.origin + img.image;
        categorized[img.type].push({
            url: fullUrl,
            caption: img.caption
        });
    });

    if ($('#all-images-container').length) {
        $('#all-images-container').remove();
    }

    let container = $('<div id="all-images-container" style="margin-top: 20px;"></div>');

    function renderCategory(title, items) {
        if (!items.length) return '';

        let html = `<h4 style="margin-bottom: 8px;">${title}</h4><div style="display:flex; flex-wrap:wrap; gap:15px;">`;
        items.forEach(img => {
            html += `
                <div style="border:1px solid #ddd; border-radius:8px; padding:10px; text-align:center; width:200px;">
                    <img src="${img.url}" style="width:180px; height:150px; object-fit:cover; border-radius:4px; cursor:pointer;" onclick="window.open('${img.url}', '_blank')">
                    <div style="margin-top: 8px; font-size: 12px; color: #666;">${img.caption}</div>
                </div>`;
        });
        html += '</div><br>';
        return html;
    }

    container.append(renderCategory('Media Preview', categorized.media));
    container.append(renderCategory('Site Images', categorized.site_photos));
    container.append(renderCategory('Measurement Sketch', categorized.measurement_sketch));

    $(frm.fields_dict.site_dimensions.grid.wrapper).after(container);
}

// 🆕 NEW: Generate Item Summary Table
function generate_item_summary(frm) {
    if (!frm.doc.boq || frm.doc.boq.length === 0) {
        remove_item_summary_table();
        return;
    }

    let bom_promises = [];
    let bom_data = {};

    // Collect all BOM data first
    frm.doc.boq.forEach(row => {
        if (row.bom) {
            let promise = frappe.call({
                method: 'frappe.client.get',
                args: {
                    doctype: 'BOM',
                    name: row.bom
                },
                callback: function(r) {
                    if (r.message) {
                        bom_data[row.bom] = {
                            entity: row.entity,
                            description: row.description,
                            bom_doc: r.message
                        };
                    }
                }
            });
            bom_promises.push(promise);
        }
    });

    // Wait for all BOM data to be fetched
    Promise.all(bom_promises).then(() => {
        process_bom_items(frm, bom_data);
    });
}

function process_bom_items(frm, bom_data) {
    let item_summary = {};
    let bom_breakdown = [];

    // Process each BOM
    Object.keys(bom_data).forEach(bom_name => {
        let bom_info = bom_data[bom_name];
        let bom_doc = bom_info.bom_doc;

        // Add BOM header info
        bom_breakdown.push({
            type: 'bom_header',
            bom_name: bom_name,
            entity: bom_info.entity,
            description: bom_info.description,
            total_cost: bom_doc.total_cost || 0
        });

        // Process BOM items
        if (bom_doc.items && bom_doc.items.length > 0) {
            bom_doc.items.forEach(item => {
                let item_code = item.item_code;
                let qty = item.qty || 0;
                let rate = item.rate || 0;
                let amount = item.amount || 0;

                // Add to BOM breakdown
                bom_breakdown.push({
                    type: 'bom_item',
                    bom_name: bom_name,
                    item_code: item_code,
                    item_name: item.item_name || '',
                    qty: qty,
                    uom: item.uom || '',
                    rate: rate,
                    amount: amount
                });

                // Add to item summary
                if (!item_summary[item_code]) {
                    item_summary[item_code] = {
                        item_name: item.item_name || '',
                        total_qty: 0,
                        uom: item.uom || '',
                        avg_rate: 0,
                        total_amount: 0,
                        bom_usage: []
                    };
                }

                item_summary[item_code].total_qty += qty;
                item_summary[item_code].total_amount += amount;
                item_summary[item_code].avg_rate = item_summary[item_code].total_amount / item_summary[item_code].total_qty;
                item_summary[item_code].bom_usage.push({
                    bom_name: bom_name,
                    entity: bom_info.entity,
                    qty: qty,
                    amount: amount
                });
            });
        }
    });

    display_item_summary_table(frm, item_summary, bom_breakdown);
}

function display_item_summary_table(frm, item_summary, bom_breakdown) {
    remove_item_summary_table();

    let container = $('<div id="item-summary-container" style="margin-top: 20px;"></div>');

    // Create Item Summary Table
    let item_table_html = `
        <div style="margin-bottom: 30px;">
            <h4 style="margin-bottom: 15px; color: #333; font-weight: bold;">📋 Item Summary</h4>
            <div style="overflow-x: auto;">
                <table style="width: 100%; border-collapse: collapse; border: 1px solid #ddd; font-size: 12px;">
                    <thead>
                        <tr style="background-color: #f8f9fa;">
                            <th style="border: 1px solid #ddd; padding: 8px; text-align: left;">#</th>
                            <th style="border: 1px solid #ddd; padding: 8px; text-align: left;">Item Code</th>
                            <th style="border: 1px solid #ddd; padding: 8px; text-align: left;">Item Name</th>
                            <th style="border: 1px solid #ddd; padding: 8px; text-align: right;">Total Qty</th>
                            <th style="border: 1px solid #ddd; padding: 8px; text-align: left;">UOM</th>
                            <th style="border: 1px solid #ddd; padding: 8px; text-align: right;">Avg Rate</th>
                            <th style="border: 1px solid #ddd; padding: 8px; text-align: right;">Total Amount</th>
                            <th style="border: 1px solid #ddd; padding: 8px; text-align: center;">Action</th>
                        </tr>
                    </thead>
                    <tbody>`;

    let row_index = 1;
    let total_summary_amount = 0;

    Object.keys(item_summary).forEach(item_code => {
        let item = item_summary[item_code];
        total_summary_amount += item.total_amount;

        item_table_html += `
            <tr style="border-bottom: 1px solid #eee;">
