        calculate_estimated_end_date(frm);
        update_operation_dates(frm);
    },

    tentative_schedule_for_execution_add: function(frm) {
        set_next_operation_date(frm);
        calculate_estimated_end_date(frm);
    },

    tentative_schedule_for_execution_remove: function(frm) {
        calculate_estimated_end_date(frm);
